"""Customer returns (RMA). A return refunds lines of a delivered order within the return window."""
import os
from dataclasses import dataclass, field
from datetime import date, timedelta

from shopkit.errors import Conflict, ShopError
from shopkit.orders.models import Order
from shopkit.utils.ids import short_code

# Deployment setting: the number of days a delivered order stays within its return window.
# Overridable with the SHOPKIT_RETURN_DAYS environment variable, defaulting to 30 days.
_RETURN_WINDOW_ENV = "SHOPKIT_RETURN_DAYS"


def _configured_return_window_days() -> int:
    raw = os.environ.get(_RETURN_WINDOW_ENV)
    if raw is None or not raw.strip():
        return 30
    try:
        value = int(raw)
    except ValueError:
        raise ShopError(f"{_RETURN_WINDOW_ENV} must be a positive integer, got {raw!r}")
    if value < 1:
        raise ShopError(f"{_RETURN_WINDOW_ENV} must be a positive integer, got {raw!r}")
    return value


RETURN_WINDOW_DAYS = _configured_return_window_days()
REASONS = ("damaged", "wrong_item", "not_as_described", "changed_mind")


class ReturnNotAllowed(Conflict):
    pass


class InvalidReturn(ShopError):
    http_status = 422


